CREATE INDEX ix_account_customer ON account(customer_id); CREATE INDEX ix_txn_account_date ON bank_transaction(account_id,transaction_date); CREATE INDEX ix_loan_customer ON loan(customer_id); CREATE TABLE schema_change_log(change_id NUMBER PRIMARY KEY, object_name VARCHAR2(100), column_name VARCHAR2(100), change_type VARCHAR2(50), old_value VARCHAR2(500), new_value VARCHAR2(500), change_date DATE DEFAULT SYSDATE); CREATE SEQUENCE schema_change_log_seq START WITH 1;
